"""Prepare corrected frontal Nene gaze plan after nine standard rows pass."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[1]
p=r/'imagegen-jobs.json';m=json.loads(p.read_text(encoding='utf-8'))
assert all(j['status']=='complete' for j in m['jobs'] if j['kind']=='row-strip')
(r/'qa/look-mechanics.md').write_text('# 短裙红袜宁宁的注视动作\n\n角色为独立头颈的人形日系Q版，保留宁宁克制的表情。正面基准双脚站定；腰、短裙、红袜、鞋和手杖下端作为定位锚点。左手在画面右侧握杖，右手低放腰部；手不抬起，杖不换边。上半身仅轻微跟随。\n\n眼球、虹膜、瞳孔、眼睑和眉形共同改变，先表现注意方向，头颈随之小幅转动。090°头部向画面右侧转约30–40°，鼻尖和眼神越过脸中央向右；270°反向向左，远侧眼收窄、近侧脸更显露。000°正面抬下巴并上视，180°正面收下巴并下视；双眼保持可读，不以闭眼冒充向下。禁止全身旋转、歪斜、脸部拉伸或只贴新瞳孔。\n\n每22.5°均匀插值头部yaw/pitch与眼睑：000→090→180→270→000。上下轴点没有横向偏转；左右轴点没有上下偏转。斜向同时包含两轴，接近上下轴时横向线索可以克制。长发轻微随头转，躯干和杖的接触连续，裙摆与鞋保持大小和落点。157.5→180及337.5→000仅一个步长，无尺寸跳变。所有16格服装始终为膝上条纹裙、露膝、红色小腿袜，不能回到旧长裤。\n\n卡面原屈膝姿势改为站立属于桌面动作演绎，服装依据完整资料页；无新配饰。九状态通过后才开始四主方向，逐行登记、检查和独立复核。\n',encoding='utf-8')
identity="Same canonical Nene animechibi, pale sagegray longhair/violet eyes, redshortjacket/goldcuffs, whitepleatedfront/blueorangebow, blackwaist andbluegoldedged splittails, ABOVE-KNEE stripedSKIRT/RED-GOLD hem, BARE knees, RED calfsocks/BLACKtops, dark REDstrap shoes/GOLDanklebows, barehands. LEFT handholds goldFLUTEDcap blackcane on screenRIGHT; RIGHT handlowatwaist. No pants/tights/gloves/hat/hookhandle."
mechanics="Feet, pelvis, skirt, socks, shoe baseline and cane lowerend stay anchored. Eyes rotate with lids/brows then HEAD/NECK follow; modest shoulder follow only. Preserve original facial anatomy; no pasted pupils, no wholebody rotation or lean. Hair follows head continuously. Calm reserved expression. All poses complete uncropped and separated by broad flat pure #FF00FF gutters. No text/labels/grid/guidelines/effects/shadows/otherprops."
card="Draw EXACTLY FOUR fullbody cardinal gaze poses in ONE horizontal strip, left-to-right: (1) UP: frontal raised chin, BOTH eyes aiming at TOP edge; (2) SCREEN-RIGHT: head yaw RIGHT, nose and pupils to RIGHT of face center, no vertical aim; (3) DOWN: frontal lowered chin, both eyes OPEN aiming DOWN, no side aim; (4) SCREEN-LEFT: head yaw LEFT, nose and pupils to LEFT of face center, far eye slightly narrower, no vertical aim. Screen coordinates mean viewer image edges. NOT four frontal stares. FIRST image is invisible four-slot spacing guide, SECOND identity, THIRD standard poses. Draw all four together as one same-size family.\n\n"+identity+"\n\n"+mechanics
(r/'prompts/look-cardinals.md').write_text(card+'\n',encoding='utf-8')
directions={9:[('000','UP ONLY, face frontal chin up, eyes up'),('022.5','UP strongly plus slightly screenRIGHT'),('045','UP and screenRIGHT equally'),('067.5','screenRIGHT strongly plus slightly UP'),('090','screenRIGHT ONLY, obvious head yaw/nose/pupils RIGHT, no up/down'),('112.5','screenRIGHT strongly plus slightly DOWN'),('135','screenRIGHT and DOWN equally'),('157.5','DOWN strongly plus slightly screenRIGHT')],10:[('180','DOWN ONLY, frontal face chin down and eyes down'),('202.5','DOWN strongly plus slightly screenLEFT'),('225','screenLEFT and DOWN equally'),('247.5','screenLEFT strongly plus slightly DOWN'),('270','screenLEFT ONLY, obvious head yaw/nose/pupils LEFT, no up/down'),('292.5','screenLEFT strongly plus slightly UP'),('315','screenLEFT and UP equally'),('337.5','UP strongly plus slightly screenLEFT')]}
for row,dirs in directions.items():
 t=f"Draw EXACTLY EIGHT SMALL fullbody gaze poses as ONE coherent horizontal strip, even spaced invisible slots. Aim each wholebody includinghair/cane ~350 pixels tall on ~2172x724 canvas, broad magenta gutters and outer margins. Row {row}, left-to-right order: "+'; '.join(f'{i+1}: {degree} {desc}' for i,(degree,desc) in enumerate(dirs))+'.\n\n'
 t+='FIRST reference spacing-only guide, SECOND canonical identity, THIRD approved standard contact, FOURTH approved UP/RIGHT/DOWN/LEFT anchors. Interpolate these cardinal head/eye families evenly, never reuse frontal stares for side directions. '
 if row==10:t+='FIFTH completed row9 is the SAME SIZE/baseline authority: match its character pixel height and width, keep shoes/cane tip at same y, begin one small step after row9 lastpose and end one step before row9 firstpose. This LEFT half must yaw and gaze LEFT; do not copy row9 RIGHT faces. '
 t+='\n\n'+identity+'\n\n'+mechanics
 (r/f'prompts/rows/look-row-{row}.md').write_text(t+'\n',encoding='utf-8');(r/f'prompts/row-retries/look-row-{row}.md').write_text(t+'\n',encoding='utf-8')
for j in m['jobs']:
 if not j['id'].startswith('look-'):continue
 j['input_images']=[{'path':f"references/layout-guides/{j['id']}.png",'role':'spacing only, invisible guide'}, {'path':'references/canonical-base.png','role':'corrected frontal skirt/red socks identity'}, {'path':'qa/contact-sheet.png','role':'approved standard poses scale/style'}]
 if j['id']!='look-cardinals':j['input_images'].append({'path':'decoded/look-anchors-approved.png','role':'approved cardinal direction families'})
 if j['id']=='look-row-10':j['input_images'].append({'path':'decoded/look-row-9.png','role':'approved row9 exact source scale/baseline and boundary continuity'})
p.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Look mechanics/prompts grounded only in corrected approved art.')
